"""Thirty original daily practice pages. S = substance track; M = compulsion track."""


def D(day, title, intention, common, substance, compulsion, reflection):
    return {
        "day": day,
        "title": title,
        "intention": intention,
        "common": common,
        "substance": substance,
        "compulsion": compulsion,
        "reflection": reflection,
    }


